import { Component, Prop, Emit } from 'vue-property-decorator';
import { PersistentSettingComponent } from '../../common/persistent-setting';
import { UserPreferences } from '../../../user-preferences';
import { ISettingsOption } from '../../../types';
import SettingsMenuAccordion from '../../settings-menu/accordion/index.vue';
import InputColourPicker from '../../input/colour-picker/index.vue';

@Component({
    name: 'SettingsItemColourPicker',
    components: {
        SettingsMenuAccordion,
        InputColourPicker
    }
})
export default class SettingsItemColourPicker extends PersistentSettingComponent<string> {
    @Prop({
        type: String,
        required: true
    })
    public label: string;

    @Prop({
        type: Array,
        required: true
    })
    public options!: Array<ISettingsOption>;

    public override value = UserPreferences.getPreference(this.prefKey, this.default, this.isGlobal, this.isMisc, this.options);

    @Emit('onChange')
    public onChange(colour: string) {
        this.value = colour;
        return this.value;
    }
}
